        let object = engine
            .objects
            .iter()
            .find(|object| object.definition_id == "GROW")
            .expect("cast object exists");
        assert_eq!(object.state.position, Vector2::new(103, 193));
        assert_eq!(object.fixed_position, FixedVec2::from_ints(103, 196));
